// Validate the decision and build the state-transition SQL.
const token = ($json.query && $json.query.token) || '';
let decision = ($json.query && $json.query.decision) || '';
if (!['approved','rejected'].includes(decision)) decision = 'rejected';
if (!/^[0-9a-fA-F-]{36}$/.test(token)) {
  return [{ json: { ok: false, message: 'Invalid token', query: 'SELECT 1 WHERE false;' } }];
}
const outreachStatus = decision === 'approved' ? 'approved' : 'cancelled';
const query = `WITH a AS (UPDATE app.approvals SET status = '${decision}', decided_at = now() WHERE token = '${token}' AND status = 'pending' RETURNING entity_id) UPDATE app.outreach o SET status = '${outreachStatus}', approved_at = CASE WHEN '${decision}' = 'approved' THEN now() ELSE approved_at END FROM a WHERE o.id = a.entity_id RETURNING o.id;`;
return [{ json: { ok: true, decision, query } }];
